-- Adminer 4.8.1 MySQL 5.5.5-10.6.7-MariaDB dump

SET NAMES utf8;
SET time_zone = '+00:00';
SET foreign_key_checks = 0;
SET sql_mode = 'NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `access_type`;
CREATE TABLE `access_type` (
  `access_name` varchar(12) NOT NULL DEFAULT '',
  `status` tinyint(1) NOT NULL DEFAULT 0,
  `remarks` text DEFAULT NULL,
  PRIMARY KEY (`access_name`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

INSERT INTO `access_type` (`access_name`, `status`, `remarks`) VALUES
('detail',	1,	'Each user can only access the menu items that have been attached to users. This type of access in terms of better security and requires a more complex settings'),
('level',	0,	'This uses the levelization access to menu item. Each user can access all the menu items that have a level less than or equal to user\'s access level');

DROP TABLE IF EXISTS `auth`;
CREATE TABLE `auth` (
  `uname` varchar(45) NOT NULL DEFAULT '',
  `menuid` int(10) unsigned NOT NULL DEFAULT 0,
  `status` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `lastuser` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`uname`,`menuid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COMMENT='InnoDB free: 11264 kB';

