DROP TABLE IF EXISTS `mscontract`;
CREATE TABLE `mscontract` (
  `compcode` char(4) NOT NULL,
  `ctrno` char(50) NOT NULL,
  `ctrdate` date NOT NULL,
  `custcode` char(10) NOT NULL,
  `ctrqty` double NOT NULL,
  `description` char(50) NOT NULL,
  `ctrstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL,
  PRIMARY KEY (`ctrno`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `mscontractpurchase`;
CREATE TABLE `mscontractpurchase` (
  `compcode` char(4) NOT NULL,
  `ctrno` char(50) NOT NULL,
  `jenis` char(6) NOT NULL,
  `vendorcode` char(10) NOT NULL,
  `kodeproduk` char(10) NOT NULL,
  `tanggaldari` date NOT NULL,
  `tanggalsampai` date NOT NULL,
  `ctrqty` double NOT NULL,
  `sisactr` double NOT NULL,
  `batasatas` double NOT NULL COMMENT 'persen',
  `batasbawah` double NOT NULL COMMENT 'persen',
  `bataskadaluwarsa` double NOT NULL COMMENT 'bulan',
  `potongan` int(11) NOT NULL,
  `ctrstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL,
  PRIMARY KEY (`ctrno`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

