DROP TABLE IF EXISTS `msproduk`;
CREATE TABLE `msproduk` (
  `kodeproduk` varchar(80) NOT NULL COMMENT 'MATNR',
  `namaproduk` varchar(50) NOT NULL COMMENT 'MAKTX',
  `satuan` varchar(10) NOT NULL COMMENT 'MEINS',
  `kriteria` enum('Pengiriman','Penerimaan') NOT NULL DEFAULT 'Pengiriman',
  `inisial` char(10) NOT NULL,
  `statusproduk` enum('0','1') NOT NULL DEFAULT '0' COMMENT 'LVORM',
  `updateby` varchar(45) NOT NULL COMMENT 'ERNAM',
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'ERDAT',
  `createby` varchar(45) NOT NULL COMMENT 'AENAM',
  `createtime` datetime NOT NULL COMMENT 'AEDAT',
  PRIMARY KEY (`kodeproduk`),
  KEY `kodeproduk` (`kodeproduk`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

