DROP TABLE IF EXISTS `mssipb`;
CREATE TABLE `mssipb` (
  `sipbno` char(50) NOT NULL,
  `ctrno` char(50) NOT NULL,
  `sipbdate` date NOT NULL,
  `kodeproduk` char(10) NOT NULL,
  `vendorcode` char(10) NOT NULL,
  `sipbqty` double NOT NULL,
  `sipbawal` double NOT NULL,
  `description` char(50) NOT NULL,
  `sipbstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `msso`;
CREATE TABLE `msso` (
