DROP TABLE IF EXISTS `msvhc`;
CREATE TABLE `msvhc` (
  `vhccode` char(15) NOT NULL,
  `typecode` char(6) NOT NULL,
  `vendorcode` char(10) NOT NULL,
  `vhctarmin` double NOT NULL,
  `vhctarmax` double NOT NULL,
  `driver` char(30) NOT NULL,
  `driversim` char(25) NOT NULL,
  `nostnk` char(100) NOT NULL,
  `tanggalstnk` date NOT NULL,
  `vhcstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(35) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

INSERT INTO `msvhc` (`vhccode`, `typecode`, `vendorcode`, `vhctarmin`, `vhctarmax`, `driver`, `driversim`, `nostnk`, `tanggalstnk`, `vhcstatus`, `updateby`, `updatetime`, `createby`, `createtime`) VALUES
