DROP TABLE IF EXISTS `msvhctype`;
CREATE TABLE `msvhctype` (
  `typecode` char(6) NOT NULL,
  `typename` char(50) NOT NULL,
  `typestatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL,
  PRIMARY KEY (`typecode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `mswilayah`;
CREATE TABLE `mswilayah` (
  `wilcode` char(4) NOT NULL,
  `wilname` char(50) NOT NULL,
  `willocation` char(20) NOT NULL,
  `wilstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL,
  PRIMARY KEY (`wilcode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


