DROP TABLE IF EXISTS `trxtimbang`;
CREATE TABLE `trxtimbang` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `indc` enum('I','O') NOT NULL DEFAULT 'I',
  `io` enum('0','1') NOT NULL DEFAULT '1',
  `idwb` char(5) NOT NULL,
  `notiket` varchar(25) NOT NULL COMMENT 'WB_TICKET',
  `kodeproduk` varchar(50) NOT NULL COMMENT 'MATNR',
  `nokontrak` varchar(50) NOT NULL COMMENT 'EBELN (kontrak pembelian)',
  `noso` varchar(50) NOT NULL COMMENT 'VBELN_1 (SO penjualan)',
  `sisaqty` int(11) NOT NULL,
  `noproductionorder` varchar(50) NOT NULL COMMENT 'AUFNR',
  `transportir` varchar(50) NOT NULL COMMENT 'TRANSP_CODE',
  `customer` varchar(50) NOT NULL COMMENT 'KUNNR',
  `supplier` varchar(50) NOT NULL COMMENT 'LIFNR',
  `waktumasuk` datetime NOT NULL COMMENT 'WBDATE_IN',
  `waktukeluar` datetime NOT NULL COMMENT 'WBDATE_OUT',
  `timbang1` int(11) NOT NULL COMMENT 'GROSS_QTY',
  `timbang2` int(11) NOT NULL COMMENT 'TARRE_QTY_MT',
  `bruto` int(11) NOT NULL,
  `kgpotongan` int(11) NOT NULL,
  `netto` int(11) NOT NULL COMMENT 'NETBG_QTY_MT',
  `satuan` varchar(10) NOT NULL COMMENT 'MEINS',
  `millcode` varchar(25) NOT NULL COMMENT 'MWERKS',
  `supir` varchar(50) NOT NULL COMMENT 'DNAME',
  `nospb` varchar(25) NOT NULL COMMENT 'SPB',
  `nokendaraan` varchar(25) NOT NULL COMMENT 'CPLATE',
  `nosegel` varchar(50) NOT NULL COMMENT 'SEALNO',
  `keterangan` varchar(50) NOT NULL COMMENT 'WB_REMARK',
  `deliverynote` varchar(50) NOT NULL COMMENT 'DLVNT',
  `sloc` varchar(10) NOT NULL COMMENT 'MLGORT',
  `batch` varchar(10) NOT NULL COMMENT 'CHARG',
  `receivedate` datetime NOT NULL COMMENT 'RCVDT',
  `receiveqty` int(11) NOT NULL COMMENT 'RCVQTY',
  `loses` int(11) NOT NULL COMMENT 'LOSS_1',
  `gainloses` int(11) NOT NULL COMMENT 'LOSS_2',
  `jjg` double DEFAULT NULL,
  `brondolan` double DEFAULT NULL,
  `intex` enum('0','1','2','3') NOT NULL COMMENT '0=eks;1=inti;2=afli;3=plasma',
  `unit` varchar(10) NOT NULL,
  `divisi` varchar(10) NOT NULL,
  `user` char(30) NOT NULL COMMENT 'operator timbang',
  PRIMARY KEY (`notiket`,`io`),
  UNIQUE KEY `id` (`id`),
  KEY `notiket` (`notiket`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `uname` varchar(45) NOT NULL DEFAULT '',
  `status` varchar(45) NOT NULL DEFAULT '0',
  `password` varchar(45) DEFAULT NULL,
  `access_level` int(10) unsigned DEFAULT 0,
  `userid` int(7) unsigned zerofill NOT NULL DEFAULT 0000000,
  `lastuser` varchar(45) NOT NULL DEFAULT 'System',
  `lastip` varchar(45) DEFAULT NULL,
  `lastcomp` varchar(45) DEFAULT NULL,
  `lastupdate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `logged` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`uname`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

