DROP TABLE IF EXISTS `wb`;
CREATE TABLE `wb` (
  `notransaksi` char(16) NOT NULL,
  `in_out` enum('I','O','II','OO') NOT NULL DEFAULT 'I',
  `waktumasuk` datetime NOT NULL,
  `waktukeluar` datetime NOT NULL,
  `beratmasuk` double NOT NULL,
  `beratkeluar` double NOT NULL,
  `netto` double NOT NULL,
  `nettosplit` double NOT NULL,
  `nettosplit2` double NOT NULL,
  `potongan` double NOT NULL,
  `potonganwajib` double NOT NULL,
  `satuan` varchar(20) NOT NULL,
  `millcode` char(10) NOT NULL,
  `kodebarang` varchar(80) NOT NULL,
  `nopo` char(40) NOT NULL,
  `multi` enum('0','1') NOT NULL DEFAULT '0',
  `kontrakbeli` char(50) NOT NULL,
  `kontrakbeli2` char(50) NOT NULL,
  `kontrakjual` char(50) NOT NULL,
  `kontrakjual2` char(50) NOT NULL,
  `notekirim` text NOT NULL,
  `supir` varchar(100) NOT NULL,
  `kernet1` varchar(100) NOT NULL,
  `kernet2` varchar(100) NOT NULL,
  `nosim` varchar(100) NOT NULL,
  `spb` varchar(40) NOT NULL,
  `qr` varchar(40) NOT NULL,
  `nokendaraan` char(25) NOT NULL,
  `qtysegel` int(11) NOT NULL,
  `segel` varchar(100) NOT NULL,
  `janjang` double NOT NULL DEFAULT 0,
  `brondolan` double NOT NULL DEFAULT 0,
  `keterangan` text NOT NULL,
  `transportir` varchar(250) NOT NULL,
  `supplier` char(10) NOT NULL,
  `customer` char(10) NOT NULL,
  `storage` char(5) NOT NULL,
  `unitcode` char(4) NOT NULL,
  `divcode` char(6) NOT NULL,
  `tipeunit` varchar(40) NOT NULL,
  `pemilik` varchar(40) NOT NULL,
  `estorigin` char(4) NOT NULL,
  `batch` char(10) NOT NULL,
  `receivedate` date NOT NULL,
  `receiveqty` double NOT NULL,
  `loses` double NOT NULL,
  `gainloses` double NOT NULL,
  `ffa` double NOT NULL,
  `moist` double NOT NULL,
  `dirt` double NOT NULL,
  `dobi` double NOT NULL,
  `printversion` int(11) NOT NULL DEFAULT 0,
  `krani` varchar(100) NOT NULL,
  `sumber` char(10) NOT NULL DEFAULT 'PABRIK' COMMENT 'timbangan PABRIK/KEBUN',
  `tiketref` char(16) NOT NULL,
  `blendsendqty` double NOT NULL,
  `wbcond` char(16) NOT NULL,
  `submittime` datetime NOT NULL,
  `FLAG_TRX` enum('N','R','D') NOT NULL DEFAULT 'N',
  `FLAG` enum('0','1') NOT NULL DEFAULT '0',
  `deletecomment` varchar(250) NOT NULL,
  `deletetime` datetime NOT NULL,
  `deleteuser` varchar(100) NOT NULL,
  `updatetime` datetime NOT NULL,
  `updateuser` varchar(100) NOT NULL,
  `postingdate` date NOT NULL,
  PRIMARY KEY (`notransaksi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

