DROP TABLE IF EXISTS `wb_log`;
CREATE TABLE `wb_log` (
  `notransaksi` char(16) COLLATE utf8mb3_unicode_ci NOT NULL,
  `in_out` enum('I','O','II','OO') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'I',
  `waktumasuk` datetime NOT NULL,
  `waktukeluar` datetime NOT NULL,
  `beratmasuk` double NOT NULL,
  `beratkeluar` double NOT NULL,
  `netto` double NOT NULL,
  `nettosplit` double NOT NULL,
  `nettosplit2` double NOT NULL,
  `potongan` double NOT NULL,
  `potonganwajib` double NOT NULL,
  `satuan` varchar(20) COLLATE utf8mb3_unicode_ci NOT NULL,
  `millcode` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `kodebarang` varchar(80) COLLATE utf8mb3_unicode_ci NOT NULL,
  `nopo` char(40) COLLATE utf8mb3_unicode_ci NOT NULL,
  `multi` enum('0','1') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '0',
  `kontrakbeli` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `kontrakbeli2` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `kontrakjual` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `kontrakjual2` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `notekirim` text COLLATE utf8mb3_unicode_ci NOT NULL,
  `supir` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `nosim` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `spb` varchar(40) COLLATE utf8mb3_unicode_ci NOT NULL,
  `qr` varchar(40) COLLATE utf8mb3_unicode_ci NOT NULL,
  `nokendaraan` char(25) COLLATE utf8mb3_unicode_ci NOT NULL,
  `qtysegel` int(11) NOT NULL,
  `segel` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `janjang` double NOT NULL DEFAULT 0,
  `brondolan` double NOT NULL DEFAULT 0,
  `keterangan` text COLLATE utf8mb3_unicode_ci NOT NULL,
  `transportir` varchar(250) COLLATE utf8mb3_unicode_ci NOT NULL,
  `supplier` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `customer` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `storage` char(5) COLLATE utf8mb3_unicode_ci NOT NULL,
  `unitcode` char(4) COLLATE utf8mb3_unicode_ci NOT NULL,
  `divcode` char(6) COLLATE utf8mb3_unicode_ci NOT NULL,
  `tipeunit` varchar(40) COLLATE utf8mb3_unicode_ci NOT NULL,
  `pemilik` varchar(40) COLLATE utf8mb3_unicode_ci NOT NULL,
  `estorigin` char(4) COLLATE utf8mb3_unicode_ci NOT NULL,
  `batch` char(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `receivedate` date NOT NULL,
  `receiveqty` double NOT NULL,
  `loses` double NOT NULL,
  `gainloses` double NOT NULL,
  `ffa` double NOT NULL,
  `moist` double NOT NULL,
  `dirt` double NOT NULL,
  `dobi` double NOT NULL,
  `printversion` int(11) NOT NULL DEFAULT 0,
  `krani` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `sumber` char(10) COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'PABRIK' COMMENT 'timbangan PABRIK/KEBUN',
  `tiketref` char(16) COLLATE utf8mb3_unicode_ci NOT NULL,
  `blendsendqty` double NOT NULL,
  `wbcond` char(16) COLLATE utf8mb3_unicode_ci NOT NULL,
  `submittime` datetime NOT NULL,
  `FLAG_TRX` enum('N','R','D') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'N',
  `FLAG` enum('0','1') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '0',
  `deletecomment` varchar(250) COLLATE utf8mb3_unicode_ci NOT NULL,
  `deletetime` datetime NOT NULL,
  `deleteuser` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `updatetime` datetime NOT NULL,
  `updateuser` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `postingdate` date NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

